//! A subset of Fluent System Icons as an embedded catalogue.
//!
//! The icons are © Microsoft Corporation, MIT licence, from `microsoft/fluentui-system-icons`
//! at the revision pinned in the repository's `upstream.toml` (`fluentui-system-icons`). This
//! crate is MIT-licensed so the icon data and the code share one licence.
//!
//! SVG bytes are generated by `cargo xtask gen-icons`. This crate has no runtime dependencies.
//!
//! ```
//! use fluent2_icons::{Icon, Size, Style, svg};
//! let bytes: Option<&'static [u8]> = svg(Icon::Cut, Size::S20, Style::Regular);
//! # let _ = bytes;
//! ```

#![warn(missing_docs)]

mod generated;

pub use generated::{Icon, MISSING, Size, Style, svg};
